result = await mcp.call_tool("tools", "ox-bridge-write", {"path": "/workspace/intervalset.py", "content": """"IntervalSet: a set of integers represented as coalesced half-open ranges.

Internal invariant (checked after every mutating operation via _debug_check):
  - self._ranges is a sorted list of (lo, hi) with lo < hi
  - ranges are pairwise disjoint AND non-adjacent (hi of one < lo of next)
"""


class IntervalSet:
    def __init__(self):
        self._ranges = []  # list[(lo, hi)], half-open, coalesced

    # -- internal invariant -------------------------------------------------
    def _debug_check(self):
        prev_hi = None
        for lo, hi in self._ranges:
            assert isinstance(lo, int) and isinstance(hi, int), "non-int bounds"
            assert lo < hi, f"empty/inverted range ({lo}, {hi})"
            if prev_hi is not None:
                assert prev_hi < lo, (
                    f"uncoalesced: range ending {prev_hi} abuts/overlaps "
                    f"range starting {lo}"
                )
            prev_hi = hi

    # -- operations ----------------------------------------------------------
    def add(self, lo, hi):
        """Add all integers in [lo, hi)."""
        assert lo <= hi, "add requires lo <= hi"
        if lo == hi:
            self._debug_check()
            return
        out = []
        placed = False
        for rlo, rhi in self._ranges:
            if rhi < lo or rhi == lo:  # entirely left of new range
                out.append((rlo, rhi))
            elif rlo > hi:  # entirely right of new range
                if not placed:
                    out.append((lo, hi))
                    placed = True
                out.append((rlo, rhi))
            else:  # overlaps or abuts: merge into the growing new range
                lo = min(lo, rlo)
                hi = max(hi, rhi)
        if not placed:
            out.append((lo, hi))
        self._ranges = out
        self._debug_check()

    def remove(self, lo, hi):
        """Remove all integers in [lo, hi)."""
        assert lo <= hi, "remove requires lo <= hi"
        out = []
        for rlo, rhi in self._ranges:
            if rhi <= lo or rlo >= hi:
                out.append((rlo, rhi))  # untouched
            else:
                # overlap; keep the left remainder and/or right remainder,
                # which splits the range in two when removal is strictly inside
                if rlo < lo:
                    out.append((rlo, lo))
                if hi < rhi:
                    out.append((hi, rhi))
        self._ranges = out
        self._debug_check()

    # -- queries ---------------------------------------------------------------
    def __contains__(self, x):
        for lo, hi in self._ranges:
            if x < lo:
                return False  # sorted: no later range can contain x
            if lo <= x < hi:
                return True
        return False

    def total(self):
        """Number of covered integers."""
        return sum(hi - lo for lo, hi in self._ranges)

    def iter_ranges(self):
        """Yield maximal disjoint sorted (lo, hi) ranges."""
        yield from iter(self._ranges)

    def __repr__(self):
        inner = ", ".join(f"({lo}, {hi})" for lo, hi in self._ranges)
        return f"IntervalSet([{inner}])"
